cssCode:
.matrix-num {
  position: absolute; top: -20px;
  font-family: monospace; font-size: 14px; font-weight: bold;
  animation: rainDrop linear infinite;
}
.profit { color: #00ff00; text-shadow: 0 0 5px #00ff00; }
.loss { color: #ff0044; text-shadow: 0 0 5px #ff0044; }

@keyframes rainDrop {
  to { transform: translateY(120vh); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;';

setInterval(() => {
  const drop = document.createElement('div');
  const isProfit = Math.random() > 0.5;
  drop.className = `matrix-num ${isProfit ? 'profit' : 'loss'}`;

  // રેન્ડમ આંકડાઓ બનાવ્યા (દા.ત. +2.4% કે -1.2%)
  const val = (Math.random() * 5).toFixed(2);
  drop.innerText = isProfit ? `+${val}%` : `-${val}%`;

  drop.style.left = `${Math.random() * 100}%`;
  drop.style.animationDuration = `${2 + Math.random() * 3}s`;

  c.appendChild(drop);
  setTimeout(() => drop.remove(), 5000); // એનિમેશન પૂરું થતાં ડિલીટ
}, 300);
